#include <bits/stdc++.h>
using namespace std;

long long recursiveCalc(long long n) {
    static unordered_map<long long, long long> cache;
    if (cache.count(n)) return cache[n];
    if (n <= 11) return min(n, 2 + (11 - n));
    long long pattern = 1, level = 1;
    while (pattern <= n) {
        pattern = pattern * 10 + 1;
        level++;
    }
    long long threshold = pattern / 10;
    if (pattern > 2 * n) {
        long long quotient = n / threshold;
        long long remainder = n % threshold;
        long long val1 = recursiveCalc(pattern - n) + level;
        long long val2 = quotient * (level - 1) + recursiveCalc(remainder);
        return cache[n] = min(val1, val2);
    } else {
        long long quotient = n / threshold;
        long long remainder = n % threshold;
        long long val1 = recursiveCalc(pattern - n) + level;
        long long val2 = quotient * (level - 1) + recursiveCalc(remainder);
        return cache[n] = min(val1, val2);
    }
}

int main() {
    long long input_num;
    cin >> input_num;
    cout << recursiveCalc(input_num);
    return 0;
}
